
"""
Pipeline orchestrator: STT Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ LLM Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ TTS.

DÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‚â€žng asyncio.Queue Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€ Ã„â€šÃ‚â€šÃƒâ€šÃ‚â€™ pre-fetch TTS:
- Producer: LLM stream Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ tÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žch cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚Ëœu Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ TTS Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Â y opus frames vÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â o queue
- Consumer: Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ã„â€šÃ‚â€žÃƒâ€šÃ‚ï¿½Ãƒâ€žÃ…Â¡Ã„Â¹Ã…Å¸Ã„â€šÃ‚â€¹Ãƒâ€šÃ‚ï¿½c queue Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ gÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â­i frames cho ESP32
Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ Trong khi Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Ëœang gÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â­i audio cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚Ëœu 1, Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚ï¿½ TTS cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚Ëœu 2 sÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃ„Â¹Ã…Â¾n rÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Å“i.
"""

