CHUNK_PUNCT_BREAKS = frozenset(",Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã„Â½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã‚Å¸Ã„â€šÃ‚â€žÃ„Â¹Ã„â€žÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€™:Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã„Â½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã‚Å¸Ã„â€šÃ‚â€žÃ„Â¹Ã„â€žÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚ï¿½Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã„â€žÃ„â€šÃ‚â€žÃƒâ€šÃ‚ï¿½Ãƒâ€žÃ…Â¡Ã„Â¹Ã…Å¸Ã„â€šÃ‚â€¹Ãƒâ€šÃ‚ï¿½")
CHUNK_SPACE_BREAK = " "


_DONE = object()

_SENTENCE_MARKER = "__sentence__"
