class ConversationPipeline:
    """
    Orchestrator: audio PCM Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ text Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ AI response Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ËœÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â„¢ audio Opus.
    Pre-fetch TTS qua asyncio.Queue de giam giat giua cac cau.
    """

    def __init__(
        self,
        stt: STTService,
        llm: LLMService,
        tts: TTSService,
        intent_detector: IntentDetectorService | None = None,
        mcp_tools: MCPToolRegistry | None = None,
        *,
        prefer_fast_only: bool = True,
    ):
        self._stt = stt
        self._llm = llm
        self._tts = tts
        self._intent_detector = intent_detector
        self._mcp_tools = mcp_tools
        self._prefer_fast_only = prefer_fast_only

    async def process(
        self,
        pcm_data: bytes,
        chat_history: list[dict],
        *,
        interaction_mode: str | None = "free_talk",
        learning_context: dict[str, str | None] | None = None,
        on_stt_result: Callable[[str], Awaitable[None]],
        on_tts_start: Callable[[], Awaitable[None]],
        on_tts_sentence: Callable[[str], Awaitable[None]],
        on_tts_audio: Callable[[bytes], Awaitable[None]],
        on_tts_stop: Callable[[], Awaitable[None]],
        on_music_action: Callable[[dict], Awaitable[None]],
        on_learning_card: Callable[[dict], Awaitable[None]] | None = None,
        assignment_provider: Callable[[], Awaitable[dict | None]] | None = None,
        on_emotion: Callable[[str], Awaitable[None]] | None = None,
        is_aborted: Callable[[], bool],
    ) -> tuple[str, str] | None:
        """Chay toan bo pipeline. Returns (user_text, assistant_response)."""

        # -- Buoc 1: STT --
        user_text = await self._stt.transcribe(pcm_data)
        if not user_text:
            logger.info("STT returned empty, skipping")
            return None

        logger.info(f"[92mÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â°Ã„â€šÃ‚â€žÃ„Â¹Ã„â€žÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â¸Ã„â€šÃ‚â€žÃ„Â¹Ã„â€žÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â¤ User: {user_text}[0m")
        await on_stt_result(user_text)

        # -- Buoc 1.5: Routing based on interaction_mode --
        if interaction_mode == "teaching":
            if learning_context is None:
                learning_context = {}
            await on_tts_start()
            reply_text = await self._handle_teaching_mode(
                user_text,
                learning_context=learning_context,
                on_tts_sentence=on_tts_sentence,
                on_tts_audio=on_tts_audio,
                is_aborted=is_aborted,
            )
            if not is_aborted():
                await on_tts_stop()
            return (user_text, reply_text)

        # Roadmap learning takes precedence if requested
        if learning_context and self._looks_like_roadmap_request(user_text):
            await on_tts_start()
            reply_text = await self._handle_roadmap_learning(
                learning_context=learning_context,
                on_tts_sentence=on_tts_sentence,
                on_tts_audio=on_tts_audio,
                on_learning_card=on_learning_card,
                is_aborted=is_aborted,
            )
            if not is_aborted():
                await on_tts_stop()
            return (user_text, reply_text)

        if learning_context and self._is_flashcard_vocab_active(learning_context):
            await on_tts_start()
            reply_text = await self._handle_flashcard_vocab_turn(
                user_text,
                learning_context=learning_context,
                on_tts_sentence=on_tts_sentence,
                on_tts_audio=on_tts_audio,
                on_learning_card=on_learning_card,
                is_aborted=is_aborted,
            )
            if not is_aborted():
                await on_tts_stop()
            return (user_text, reply_text)

