        # LLM intent Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â´i khi trÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚ï¿½ learning_topic nhÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€ Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â°ng thiÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã…Å¸u learning_mode/topic_id.
        # TÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€¦ suy luÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â­n mode/topic tÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Â¤ cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚Ëœu user Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€ Ã„â€šÃ‚â€šÃƒâ€šÃ‚â€™ trÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žnh lÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚â€¡p hÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ã„â€šÃ‚â€žÃƒâ€šÃ‚ï¿½Ãƒâ€žÃ…Â¡Ã„Â¹Ã…Å¸Ã„â€šÃ‚â€¹Ãƒâ€šÃ‚ï¿½i lÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€ži.
        inferred_topic = None
