            GRACE_S = 0.05  # nghÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚Â° 50ms giÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã„Â½a cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žc cÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€¹Ãƒâ€šÃ‚Ëœu cho tÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€¦ nhiÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¾n
