                self._tts.synthesize("Xin lÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚â€�i, mÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ã„Â¹Ã„â€žnh chÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€ Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â°a phÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žt Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€¹Ã‚ËœÃ„â€šÃ‚â€šÃƒâ€šÃ‚â‚¬Ã„â€šÃ‚â€šÃƒâ€šÃ‚ËœÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚â€ Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â°Ã„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€žÃƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€žÃ‹ï¿½Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚ï¿½c bÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â i nÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â y lÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃƒâ€žÃ…Â¡Ãƒâ€šÃ‚Å¸c nÃ„â€šÃ‚â€žÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Æ’Ãƒâ€žÃ‚â€šÃƒâ€šÃ‚â€šÃ„â€šÃ‚â€šÃƒâ€šÃ‚Â y."),
                on_tts_audio=on_tts_audio,
